-- Widget beauty scan: one scan in the demo-retailer widget reads the colour
-- season, face shape and skin type together (services/skin-scanning
-- /analyze-beauty). Each result is kept against the guest widget session so
-- the widget chat can ground its replies in it.
--
-- `request_id` is generated by the widget per scan, so a retried upload
-- updates its row instead of saving the scan twice. `report` is the full
-- service response (no images — frames are never stored); the headline
-- readings are columns for reporting. `shade_product_ids` are the catalog
-- shades shown for the season's palette, for attribution.
CREATE TABLE IF NOT EXISTS widget_beauty_scans (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id UUID NOT NULL REFERENCES widget_sessions(id) ON DELETE CASCADE,
  request_id UUID NOT NULL,
  report JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (session_id, request_id)
);

ALTER TABLE widget_beauty_scans ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE widget_beauty_scans
  ADD COLUMN IF NOT EXISTS season_key TEXT,
  ADD COLUMN IF NOT EXISTS season_confidence REAL,
  ADD COLUMN IF NOT EXISTS undertone TEXT,
  ADD COLUMN IF NOT EXISTS face_shape_key TEXT,
  ADD COLUMN IF NOT EXISTS skin_type_key TEXT,
  ADD COLUMN IF NOT EXISTS skin_overall REAL,
  ADD COLUMN IF NOT EXISTS shade_product_ids UUID[];

CREATE INDEX IF NOT EXISTS idx_widget_beauty_scans_session ON widget_beauty_scans (session_id, created_at DESC);
